using System;using System.IO;using System.Text;using System.Linq;using System.Globalization;using System.Collections.Generic;using System.Collections.ObjectModel;
namespace Frociart {
    // Data-only code templates. No reflection, file includes, executable expressions or host callbacks.
    internal sealed class FlowCodeTemplate {
        internal const int MaxCharacters=262144,MaxDefinitionCharacters=MaxCharacters+2048,MaxBytes=1048576,MaxNodes=8192,MaxDepth=64,MaxOperations=500000;
        internal const string FpgtInstructions="Modello .fpgt importato. Il linguaggio e i limiti dipendono dal modello; controlla il sorgente e provalo con gli strumenti del linguaggio. L’app non esegue il codice del modello.";
        internal readonly string Name,Base,Extension,Instructions,Body;
        internal readonly FlowFpgtSyntax Fpgt;
        internal string ExportText {get{return Fpgt==null?Text:Body;}}
        internal string FileExtension {get{return Fpgt==null?"frotemplate":"fpgt";}}
        internal readonly bool CaseSensitive;
        internal readonly string Text;
        private readonly List<Node> nodes;private readonly Dictionary<string,Macro> macros;
        private FlowCodeTemplate(Dictionary<string,string> fields,string body){
            Name=Field(fields,"name",80);Base=Field(fields,"base",20).ToLowerInvariant();Extension=Field(fields,"extension",16);Instructions=Field(fields,"instructions",1000,false);Body=body;
            if(body.Length>MaxCharacters)throw new ArgumentException("Il corpo del modello supera 262144 caratteri.");
            if(Base!="custom"&&Base!="flowgorithm"&&FlowSourceTarget.Find(Base)==null)throw new ArgumentException("Il generatore di base del modello non è disponibile.");
            if(!System.Text.RegularExpressions.Regex.IsMatch(Extension,"^[a-zA-Z][a-zA-Z0-9]{0,15}$"))throw new ArgumentException("L’estensione deve contenere solo lettere e numeri, senza punto.");
            string sensitive;CaseSensitive=!fields.TryGetValue("case sensitive",out sensitive)||sensitive=="true";if(sensitive!=null&&sensitive!="true"&&sensitive!="false")throw new ArgumentException("Case Sensitive deve essere true o false.");
            if(Base=="flowgorithm"){Fpgt=FlowFpgtSyntax.Parse(body);CaseSensitive=Fpgt.CaseSensitive;Extension=Fpgt.Extension;nodes=new List<Node>();macros=new Dictionary<string,Macro>();}else{var parser=new Parser(body);nodes=parser.Parse();macros=parser.Macros;}Text=Encode();
        }
        private static string Field(Dictionary<string,string> fields,string key,int limit,bool required=true){string value;if(!fields.TryGetValue(key,out value))value="";if(required&&String.IsNullOrWhiteSpace(value)||value.Length>limit||value.Any(c=>Char.IsControl(c)))throw new ArgumentException("Campo del modello non valido: "+key+".");return value;}
        internal static FlowCodeTemplate Parse(string text){
            if(text==null||text.Length>MaxDefinitionCharacters)throw new ArgumentException("Il modello supera il limite di dimensione.");ValidateUnicode(text);text=text.TrimStart('\ufeff').Replace("\r\n","\n").Replace('\r','\n');
            string first=text.Split('\n').Select(s=>s.Trim()).FirstOrDefault(s=>s.Length>0&&!s.StartsWith(";",StringComparison.Ordinal));if(first!=null&&first.StartsWith("[",StringComparison.Ordinal)&&!first.Equals("[Frociart Template]",StringComparison.OrdinalIgnoreCase)){var fpgt=FlowFpgtSyntax.Parse(text);return new FlowCodeTemplate(new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"name",fpgt.Name},{"base","flowgorithm"},{"extension",fpgt.Extension},{"instructions",FpgtInstructions},{"case sensitive",fpgt.CaseSensitive?"true":"false"}},text);}
            var fields=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);string[] lines=text.Split('\n');bool header=false;int body=-1;
            for(int i=0;i<lines.Length;i++){string line=lines[i].Trim();if(line.Length==0||line.StartsWith(";",StringComparison.Ordinal))continue;if(line=="[Frociart Template]"){if(header)throw new ArgumentException("Intestazione del modello duplicata.");header=true;continue;}if(line=="[Template]"){body=i+1;break;}if(!header)throw new ArgumentException("Manca [Frociart Template].");int equal=line.IndexOf('=');if(equal<=0)throw new ArgumentException("Intestazione del modello non valida alla riga "+(i+1)+".");string key=line.Substring(0,equal).Trim(),value=line.Substring(equal+1).Trim();if(!new[]{"version","name","base","extension","instructions","case sensitive"}.Contains(key.ToLowerInvariant()))throw new ArgumentException("Campo del modello sconosciuto: "+key+".");if(fields.ContainsKey(key))throw new ArgumentException("Campo del modello duplicato: "+key+".");fields.Add(key,value);}
            if(body<0||!header)throw new ArgumentException("Manca la sezione [Template].");string version;if(!fields.TryGetValue("version",out version)||version!="1")throw new ArgumentException("Versione del modello non supportata.");return new FlowCodeTemplate(fields,String.Join("\n",lines.Skip(body)));
        }
        internal static FlowCodeTemplate Create(string name,string language,string extension,string instructions,string body,bool caseSensitive=true){return Parse("[Frociart Template]\nVersion = 1\nName = "+name+"\nBase = "+language+"\nExtension = "+extension+"\nInstructions = "+instructions+"\nCase Sensitive = "+(caseSensitive?"true":"false")+"\n[Template]\n"+body);}
        private string Encode(){return "[Frociart Template]\nVersion = 1\nName = "+Name+"\nBase = "+Base+"\nExtension = "+Extension+"\nInstructions = "+Instructions+"\nCase Sensitive = "+(CaseSensitive?"true":"false")+"\n[Template]\n"+Body;}
        internal FlowSourceText Generate(FlowSource.Program program,FlowSourceText source){return GenerateTyped(program,source,null);}
        internal FlowSourceText GenerateTyped(FlowSource.Program program,FlowSourceText source,IDictionary<string,FlowDataType> choices){if(program==null||!program.CanGenerate)throw new ArgumentException("Correggi il diagramma prima di generare il codice.");if(Fpgt!=null)return FlowFpgt.Generate(Fpgt,program,choices);if(Base!="custom"&&(source==null||source.Language!=Base))throw new ArgumentException("Il sorgente di base non corrisponde al modello.");var engine=new Engine(this,program,source);try{return engine.Run();}catch(FlowException error){throw new ArgumentException(error.Message,error);}}
        internal static string Decode(byte[] bytes){if(bytes==null||bytes.Length>MaxBytes)throw new ArgumentException("Il modello supera 1 MiB.");try{if(bytes.Length>=2&&bytes[0]==255&&bytes[1]==254)return new UnicodeEncoding(false,true,true).GetString(bytes,2,bytes.Length-2);if(bytes.Length>=2&&bytes[0]==254&&bytes[1]==255)return new UnicodeEncoding(true,true,true).GetString(bytes,2,bytes.Length-2);return new UTF8Encoding(false,true).GetString(bytes);}catch(DecoderFallbackException){throw new ArgumentException("Il modello non contiene testo UTF-8 o UTF-16 con BOM valido.");}}
        private static void ValidateUnicode(string text){for(int i=0;i<text.Length;i++){char ch=text[i];if(Char.IsHighSurrogate(ch)){if(++i>=text.Length||!Char.IsLowSurrogate(text[i]))throw new ArgumentException("Il modello contiene un carattere Unicode incompleto.");}else if(Char.IsLowSurrogate(ch))throw new ArgumentException("Il modello contiene un carattere Unicode incompleto.");if(ch=='\0')throw new ArgumentException("Il modello contiene un carattere nullo.");}}
        private static ArgumentException Error(int line,string message){return new ArgumentException("Modello · riga "+line+": "+message);}
        private static bool NameToken(string text){return System.Text.RegularExpressions.Regex.IsMatch(text,"^[A-Za-z_][A-Za-z_0-9]*$");}
        private sealed class Token {internal string Kind,Text;internal int Line;}
        private sealed class Node {internal string Kind,Text,Name;internal int Line;internal Query Query;internal List<Node> Body,Otherwise;}
        private sealed class Macro {internal string Parameter;internal List<Node> Body;}
        private sealed class Filter {internal string Name;internal object Argument;}
        private sealed class Query {internal string[] Path;internal object Constant;internal bool IsConstant;internal List<Filter> Filters=new List<Filter>();}
        private sealed class Parser {
            readonly List<Token> tokens=new List<Token>();int position,count,depth;internal readonly Dictionary<string,Macro> Macros=new Dictionary<string,Macro>(StringComparer.Ordinal);
            static int Closing(string text,int start,string close){char quote='\0';for(int i=start;i+1<text.Length;i++){char ch=text[i];if(quote!='\0'){if(ch=='\\')i++;else if(ch==quote)quote='\0';}else if(ch=='\''||ch=='"')quote=ch;else if(ch==close[0]&&text[i+1]==close[1])return i;}return -1;}
            void Add(Token token){if(tokens.Count>=MaxNodes*2)throw Error(token.Line,"troppi tag.");tokens.Add(token);}
            internal Parser(string body){int at=0,line=1;while(at<body.Length){int next=body.IndexOf('{',at);if(next<0)next=body.Length;if(next>at){string value=body.Substring(at,next-at);Add(new Token{Kind="text",Text=value,Line=line});line+=value.Count(c=>c=='\n');at=next;continue;}string open=at+1<body.Length?body.Substring(at,2):"";if(open!="{{"&&open!="{%"&&open!="{#"){Add(new Token{Kind="text",Text="{",Line=line});at++;continue;}string close=open=="{{"?"}}":open=="{%"?"%}":"#}";int end=open=="{#"?body.IndexOf(close,at+2,StringComparison.Ordinal):Closing(body,at+2,close);if(end<0)throw Error(line,"tag non chiuso.");string text=body.Substring(at+2,end-at-2).Trim();int origin=line;line+=body.Substring(at,end+2-at).Count(c=>c=='\n');at=end+2;
                if(open=="{#")continue;if(open=="{%"&&text=="raw"){int stop=body.IndexOf("{% endraw %}",at,StringComparison.Ordinal);if(stop<0)throw Error(origin,"manca endraw.");string raw=body.Substring(at,stop-at);Add(new Token{Kind="text",Text=raw,Line=line});line+=raw.Count(c=>c=='\n');at=stop+12;continue;}Add(new Token{Kind=open=="{{"?"value":"tag",Text=text,Line=origin});}}
            internal List<Node> Parse(){string stop;var result=Block(new string[0],out stop);if(stop!=null)throw Error(tokens[position-1].Line,"tag inatteso: "+stop+".");return result;}
            List<Node> Block(string[] stops,out string stop){if(++depth>MaxDepth)throw Error(position<tokens.Count?tokens[position].Line:1,"annidamento eccessivo.");var result=new List<Node>();stop=null;try{while(position<tokens.Count){Token token=tokens[position++];if(token.Kind=="tag"&&stops.Contains(token.Text)){stop=token.Text;return result;}if(++count>MaxNodes)throw Error(token.Line,"troppi elementi nel modello.");var node=new Node{Kind=token.Kind,Text=token.Text,Line=token.Line};if(token.Kind=="value")node.Query=ParseQuery(token.Text,token.Line);else if(token.Kind=="tag"){
                    string text=token.Text;string end;
                    if(text.StartsWith("if ",StringComparison.Ordinal)){node.Kind="if";node.Query=ParseQuery(text.Substring(3),token.Line);node.Body=Block(new[]{"else","endif"},out end);if(end=="else")node.Otherwise=Block(new[]{"endif"},out end);if(end!="endif")throw Error(token.Line,"manca endif.");}
                    else if(text.StartsWith("for ",StringComparison.Ordinal)){var match=System.Text.RegularExpressions.Regex.Match(text,"^for ([A-Za-z_][A-Za-z_0-9]*) in (.+)$");if(!match.Success)throw Error(token.Line,"usa for elemento in elenco.");node.Kind="for";node.Name=match.Groups[1].Value;if(node.Name=="loop")throw Error(token.Line,"loop è riservato ai dati del ciclo.");node.Query=ParseQuery(match.Groups[2].Value,token.Line);node.Body=Block(new[]{"else","endfor"},out end);if(end=="else")node.Otherwise=Block(new[]{"endfor"},out end);if(end!="endfor")throw Error(token.Line,"manca endfor.");}
                    else if(text.StartsWith("macro ",StringComparison.Ordinal)){string[] parts=text.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);if(depth!=1||parts.Length!=3||!NameToken(parts[1])||!NameToken(parts[2])||Macros.ContainsKey(parts[1]))throw Error(token.Line,"macro non valida o duplicata.");var body=Block(new[]{"endmacro"},out end);if(end!="endmacro")throw Error(token.Line,"manca endmacro.");Macros.Add(parts[1],new Macro{Parameter=parts[2],Body=body});continue;}
                    else if(text.StartsWith("render ",StringComparison.Ordinal)){int split=text.IndexOf(' ',7);if(split<0||!NameToken(text.Substring(7,split-7)))throw Error(token.Line,"usa render nome valore.");node.Kind="render";node.Name=text.Substring(7,split-7);node.Query=ParseQuery(text.Substring(split+1),token.Line);}
                    else if(text.StartsWith("require ",StringComparison.Ordinal)){var parts=Split(text.Substring(8),'|',token.Line);if(parts.Count<2)throw Error(token.Line,"usa require condizione | \"messaggio\".");node.Kind="require";node.Query=ParseQuery(String.Join("|",parts.Take(parts.Count-1)),token.Line);object message=Constant(parts[parts.Count-1].Trim(),token.Line);if(!(message is string))throw Error(token.Line,"il messaggio di require deve essere un testo.");node.Text=(string)message;}
                    else throw Error(token.Line,"tag sconosciuto: "+text+".");
                }result.Add(node);}return result;}finally{depth--;}}
        }
        private static List<string> Split(string text,char separator,int line){var result=new List<string>();int at=0;char quote='\0';bool escape=false;for(int i=0;i<text.Length;i++){char ch=text[i];if(escape){escape=false;continue;}if(quote!='\0'){if(ch=='\\')escape=true;else if(ch==quote)quote='\0';}else if(ch=='\''||ch=='"')quote=ch;else if(ch==separator){result.Add(text.Substring(at,i-at));at=i+1;}}if(quote!='\0'||escape)throw Error(line,"testo tra virgolette non chiuso.");result.Add(text.Substring(at));return result;}
        private static object Constant(string text,int line){if(text=="true")return true;if(text=="false")return false;if(text=="null")return null;double number;if(System.Text.RegularExpressions.Regex.IsMatch(text,"^-?(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?$")&&Double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out number)&&!Double.IsInfinity(number))return number;
            if(text.Length<2||text[0]!='"'&&text[0]!='\''||text[text.Length-1]!=text[0])throw Error(line,"valore costante non valido.");char quote=text[0];var value=new StringBuilder();for(int i=1;i<text.Length-1;i++){char ch=text[i];if(ch==quote)throw Error(line,"virgolette inattese.");if(ch=='\\'){if(++i>=text.Length-1)throw Error(line,"escape incompleto.");ch=text[i];switch(ch){case 'n':ch='\n';break;case 'r':ch='\r';break;case 't':ch='\t';break;case '\\':case '\'':case '"':break;case 'u':int code;if(i+4>=text.Length-1||!Int32.TryParse(text.Substring(i+1,4),NumberStyles.HexNumber,CultureInfo.InvariantCulture,out code))throw Error(line,"escape Unicode non valido.");ch=(char)code;i+=4;break;default:throw Error(line,"escape sconosciuto.");}}value.Append(ch);}ValidateUnicode(value.ToString());return value.ToString();}
        private static Query ParseQuery(string text,int line){var parts=Split(text,'|',line);string path=parts[0].Trim();var query=new Query();if(path=="true"||path=="false"||path=="null"||path.StartsWith("\"",StringComparison.Ordinal)||path.StartsWith("'",StringComparison.Ordinal)||path.Length>0&&(path[0]=='-'||Char.IsDigit(path[0]))){query.IsConstant=true;query.Constant=Constant(path,line);}else{if(!System.Text.RegularExpressions.Regex.IsMatch(path,"^[A-Za-z_][A-Za-z_0-9]*(?:\\.(?:[A-Za-z_][A-Za-z_0-9]*|[0-9]+))*$"))throw Error(line,"usa un campo, per esempio program.main.blocks.");query.Path=path.Split('.');}
            foreach(string part in parts.Skip(1)){var filter=Split(part,':',line);string name=filter[0].Trim();if(filter.Count>2||!new[]{"literal","identifier","number","count","join","default","upper","lower","not","equals"}.Contains(name))throw Error(line,"filtro sconosciuto: "+name+".");bool argument=name=="join"||name=="default"||name=="equals";if(argument!=(filter.Count==2))throw Error(line,"argomento del filtro non valido: "+name+".");query.Filters.Add(new Filter{Name=name,Argument=argument?Constant(filter[1].Trim(),line):null});}return query;
        }
        internal sealed class Deferred {private readonly Lazy<object> value;internal Deferred(Func<object> factory){value=new Lazy<object>(factory);}internal object Get(){return value.Value;}}
        internal sealed class Data {internal readonly Dictionary<string,object> Fields=new Dictionary<string,object>(StringComparer.Ordinal);internal readonly FlowSourceText.Origin Origin;internal Data(FlowSourceText.Origin origin=null){Origin=origin;}internal Data Put(string name,object value){Fields.Add(name,value);return this;}}
        private sealed class Engine {
            readonly FlowCodeTemplate definition;readonly FlowSourceText.Builder output;readonly FlowSourceText source;readonly List<Dictionary<string,object>> stack=new List<Dictionary<string,object>>();readonly StringBuilder line=new StringBuilder();readonly List<FlowSourceText.Origin> origins=new List<FlowSourceText.Origin>();readonly Dictionary<string,string> identifiers=new Dictionary<string,string>(StringComparer.Ordinal);readonly HashSet<string> used;int operations,characters,recursion;FlowSourceText.Origin lastOrigin;
            internal Engine(FlowCodeTemplate definition,FlowSource.Program program,FlowSourceText source){this.definition=definition;this.source=source;output=new FlowSourceText.Builder(program,definition.Base);used=new HashSet<string>(definition.CaseSensitive?StringComparer.Ordinal:StringComparer.OrdinalIgnoreCase);stack.Add(new Dictionary<string,object>{{"project",new Data().Put("title",program.Title)},{"program",FlowTemplateData.Create(program)},{"source",source}});}
            internal FlowSourceText Run(){Render(definition.nodes,null);if(line.Length>0)Flush();return output.Build();}
            void Tick(int number){operations+=number;if(operations>MaxOperations)throw new ArgumentException("Il modello supera il limite di lavoro. Riduci cicli o macro ricorsive.");}
            void Render(List<Node> nodes,FlowSourceText.Origin origin){if(nodes==null)return;if(++recursion>128)throw new ArgumentException("Il modello supera 128 livelli di macro e blocchi.");try{foreach(var node in nodes){Tick(1);switch(node.Kind){case "text":Emit(node.Text,origin);break;case "value":{object value=Evaluate(node.Query,node.Line);Write(value,lastOrigin??origin,node.Line);break;}case "if":Render(Truthy(Evaluate(node.Query,node.Line))?node.Body:node.Otherwise,origin);break;case "require":if(!Truthy(Evaluate(node.Query,node.Line)))throw Error(node.Line,node.Text);break;case "for":{var value=Evaluate(node.Query,node.Line) as IList<object>;if(value==null)throw Error(node.Line,"for richiede un elenco.");Tick(value.Count);if(value.Count==0)Render(node.Otherwise,origin);for(int i=0;i<value.Count;i++){object item=value[i] is Deferred?((Deferred)value[i]).Get():value[i];var data=item as Data;stack.Add(new Dictionary<string,object>{{node.Name,item},{"loop",new Data().Put("index",(double)i+1).Put("index0",(double)i).Put("first",i==0).Put("last",i+1==value.Count).Put("length",(double)value.Count)}});try{Render(node.Body,data==null?origin:data.Origin??origin);}finally{stack.RemoveAt(stack.Count-1);}}break;}case "render":{Macro macro;if(!definition.macros.TryGetValue(node.Name,out macro))throw Error(node.Line,"macro non trovata: "+node.Name+".");object value=Evaluate(node.Query,node.Line);var data=value as Data;stack.Add(new Dictionary<string,object>{{macro.Parameter,value}});try{Render(macro.Body,data==null?origin:data.Origin??origin);}finally{stack.RemoveAt(stack.Count-1);}break;}default:throw Error(node.Line,"elemento non valido.");}}}finally{recursion--;}}
            object Evaluate(Query query,int at){Tick(1);lastOrigin=null;object value=query.Constant;if(!query.IsConstant){bool found=false;for(int i=stack.Count-1;i>=0;i--)if(stack[i].TryGetValue(query.Path[0],out value)){found=true;break;}if(!found)throw Error(at,"campo sconosciuto: "+query.Path[0]+".");if(value is Deferred)value=((Deferred)value).Get();foreach(string key in query.Path.Skip(1)){var data=value as Data;if(data!=null&&data.Origin!=null)lastOrigin=data.Origin;var list=value as IList<object>;int index;if(data!=null){if(!data.Fields.TryGetValue(key,out value))throw Error(at,"campo sconosciuto: "+key+".");}else if(list!=null&&Int32.TryParse(key,out index)&&index>=0&&index<list.Count)value=list[index];else throw Error(at,"il percorso non contiene il campo "+key+".");if(value is Deferred)value=((Deferred)value).Get();}}
                foreach(var filter in query.Filters){Tick(1);if(value is FlowSourceText)throw Error(at,"il sorgente completo non accetta filtri.");switch(filter.Name){case "equals":value=Object.Equals(value,filter.Argument);break;case "default":if(!Truthy(value))value=filter.Argument;break;case "not":value=!Truthy(value);break;case "count":var list=value as IList<object>;if(value!=null&&list==null&&!(value is string))throw Error(at,"count richiede un testo o un elenco.");value=(double)(list!=null?list.Count:value is string?((string)value).Length:0);break;case "join":var items=value as IList<object>;if(items==null||!(filter.Argument is string))throw Error(at,"join richiede un elenco e un separatore di testo.");var joined=new StringBuilder();bool first=true;foreach(object item in items){if(!first)joined.Append((string)filter.Argument);first=false;joined.Append(Scalar(item,at));if(joined.Length>FlowSourceText.Builder.MaxCharacters)throw Error(at,"testo generato troppo lungo.");}value=joined.ToString();break;case "literal":value=Literal(Scalar(value,at));break;case "number":if(!(value is double))throw Error(at,"number richiede un numero.");value=Number((double)value);break;case "identifier":value=Identifier(Scalar(value,at));break;case "upper":case "lower":string input=Scalar(value,at);value=new String(input.Select(ch=>filter.Name=="upper"?Char.ToUpperInvariant(ch):Char.ToLowerInvariant(ch)).ToArray());break;}}
                return value;
            }
            string Literal(string value){switch(definition.Base){case "powershell":return FlowPowerShell.Literal(value);case "php":return FlowPhp.Literal(value);case "ruby":return FlowRuby.Literal(value);case "python":return FlowPython.Literal(value);case "java":return FlowJava.Literal(value);case "groovy":return FlowGroovy.Literal(value);case "kotlin":return FlowKotlin.Literal(value);case "csharp":return FlowCSharp.Literal(value);case "vbnet":return FlowVisualBasic.Literal(value);case "cpp":return FlowCpp.Literal(value);default:return FlowJavaScript.Literal(value);}}
            string Number(double value){switch(definition.Base){case "powershell":return FlowPowerShell.TemplateNumber(value,source);case "php":return FlowPhp.TemplateNumber(value);case "ruby":return FlowRuby.TemplateNumber(value);case "python":return FlowPython.TemplateNumber(value);case "java":return FlowJava.TemplateNumber(value);case "groovy":return FlowGroovy.TemplateNumber(value);case "kotlin":return FlowKotlin.TemplateNumber(value);case "csharp":return FlowCSharp.TemplateNumber(value);case "vbnet":return FlowVisualBasic.TemplateNumber(value);case "cpp":return FlowCpp.TemplateNumber(value);default:return FlowJavaScript.TemplateNumber(value);}}
            string Identifier(string raw){string value;if(identifiers.TryGetValue(raw,out value))return value;var b=new StringBuilder("user_");foreach(char ch in raw)if(ch>='a'&&ch<='z'||ch>='A'&&ch<='Z'||ch>='0'&&ch<='9')b.Append(ch);else b.Append("_u").Append(((int)ch).ToString("x4"));string seed=b.ToString();value=seed;int suffix=2;while(!used.Add(value))value=seed+"_"+(suffix++).ToString(CultureInfo.InvariantCulture);identifiers.Add(raw,value);return value;}
            static bool Truthy(object value){if(value==null)return false;if(value is bool)return(bool)value;if(value is double)return(double)value!=0;if(value is string)return((string)value).Length>0;var list=value as IList<object>;return list==null||list.Count>0;}
            static string Scalar(object value,int at){if(value==null)return "";if(value is string)return(string)value;if(value is bool)return(bool)value?"true":"false";if(value is double)return ValueFormatter.Format(value);throw Error(at,"usa un campo semplice oppure un ciclo per questo valore.");}
            void Write(object value,FlowSourceText.Origin origin,int at){var code=value as FlowSourceText;if(code==null){Emit(Scalar(value,at),origin);return;}Tick(code.Lines.Count);foreach(var item in code.Lines){foreach(var mapped in item.Origins)AddOrigin(mapped);Emit(code.Text.Substring(item.Start,item.Length)+"\n",null);}}
            void AddOrigin(FlowSourceText.Origin origin){if(origin!=null&&!origins.Any(o=>o.Matches(origin.FunctionId,origin.NodeId)))origins.Add(origin);}
            void Emit(string value,FlowSourceText.Origin origin){value=value.Replace("\r\n","\n").Replace('\r','\n');if(value.Length>FlowSourceText.Builder.MaxCharacters-characters)throw new ArgumentException("Il codice generato supera il limite di dimensione.");characters+=value.Length;foreach(char ch in value){AddOrigin(origin);if(ch=='\n')Flush();else line.Append(ch);}}
            void Flush(){output.AddLine(line.ToString(),0,origins.ToArray());line.Clear();origins.Clear();}
        }
    }
}
